{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    required = ("nodes", "core_distance", "distances")
    if any(name not in case for name in required):
        raise ValueError("missing required field")

    nodes = case["nodes"]
    core_input = case["core_distance"]
    distances = case["distances"]
    if not isinstance(nodes, list) or not isinstance(core_input, dict) or not isinstance(distances, list):
        raise ValueError("invalid field type")
    if not nodes:
        raise ValueError("nodes must not be empty")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("node identifiers must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    if len(core_input) != len(nodes) or any(node not in core_input for node in nodes):
        raise ValueError("core distances must match nodes exactly")

    core_distance = {}
    positions = {}
    for position, node in enumerate(nodes):
        value = core_input[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
            raise ValueError("invalid core distance")
        core_distance[node] = value
        positions[node] = position

    edges = []
    seen_pairs = set()
    for source_position, item in enumerate(distances):
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("each distance must be a three-item sequence")
        left, right, distance = item
        if left not in positions or right not in positions or left == right:
            raise ValueError("distance endpoint is invalid")
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or not math.isfinite(distance) or distance < 0:
            raise ValueError("invalid distance")
        if left > right:
            left, right = right, left
        pair = (left, right)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance")
        seen_pairs.add(pair)
        weight = max(core_distance[left], core_distance[right], distance)
        edges.append((weight, left, right, distance, source_position))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = list(range(len(nodes)))
    rank = [0] * len(nodes)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    selected = []
    for weight, left, right, distance, source_position in edges:
        left_root = find(positions[left])
        right_root = find(positions[right])
        if left_root == right_root:
            continue
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        selected.append((weight, left, right, distance, source_position))
        if len(selected) == len(nodes) - 1:
            break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    def edge_object(edge):
        weight, left, right, distance, source_position = edge
        return {
            "left": left,
            "right": right,
            "distance": distance,
            "weight": weight,
        }

    total_weight = sum(edge[0] for edge in selected)
    return {
        "core_distance": core_distance,
        "mutual_reachability": [edge_object(edge) for edge in edges],
        "mst_edges": [edge_object(edge) for edge in selected],
        "total_weight": total_weight,
    }
"}
